package dk.jamesbabz.madkursus.outbound.recipetemplate;
import java.util.*;import dk.jamesbabz.madkursus.outbound.producttemplate.mappers.ProductTemplateEntityMapper;import dk.jamesbabz.madkursus.outbound.recipetemplate.details.*;import dk.jamesbabz.madkursus.service.models.*;import dk.jamesbabz.madkursus.service.ports.RecipeTemplatePort;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component @RequiredArgsConstructor public class RecipeTemplateAdapterImpl implements RecipeTemplatePort{private final RecipeTemplateJpaRepository repository;private final ProductTemplateEntityMapper products;@Transactional(readOnly=true)public List<RecipeTemplate> search(String q){return repository.search(q==null?"":q.trim()).stream().map(this::map).toList();}@Transactional(readOnly=true)public Optional<RecipeTemplate> findById(UUID id){return repository.findByIdAndActiveTrue(id).map(this::map);}private RecipeTemplate map(RecipeTemplateEntity e){return new RecipeTemplate(e.getId(),e.getName(),e.getDescription(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt(),e.getIngredients().stream().map(i->new RecipeTemplateIngredient(i.getId(),products.toModel(i.getProductTemplate()),i.getQuantity(),i.getUnit(),i.getPreparation(),i.getSortOrder())).toList(),e.getSteps().stream().map(s->new RecipeTemplateStep(s.getId(),s.getStepType(),s.getInstruction(),s.getSortOrder(),s.getCookingProcessId(),s.getBindings().stream().map(b->new CookingProcessBinding(b.getId(),b.getParameterKey(),b.getRecipeIngredientId(),b.getProductTemplate()==null?null:products.toModel(b.getProductTemplate()),new CookingProcessValue(b.getQuantity(),b.getUnit(),b.getDurationSeconds(),b.getTemperatureCelsius(),b.getHeatLevel(),b.getNumber(),b.getText()))).toList())).toList());}}
